function ApiFetcher() {
  const [users, setUsers] = React.useState([]);
  React.useEffect(() => {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => { setUsers(data); })
      .catch(err => console.error(err));
  }, []);
  return (
    <div>
      <h1>User Directory</h1>
      {users.map(u => (
        <div key={u.id}>
          <h3>{u.name}</h3>
          <p>{u.email}</p>
        </div>
      ))}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<ApiFetcher />);

function ApiFetcher() {
  const [users, setUsers] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  React.useEffect(() => {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => {
        setUsers(data);
        setLoading(false);
      })
      .catch(err => console.error(err));
  }, []);
  return (
    <div>
      <h1>User Directory</h1>
      {loading ? (
        <p>Loading...</p>
      ) : (
        users.map(u => (
          <div key={u.id}>
            <h3>{u.name}</h3>
            <p>{u.email}</p>
          </div>
        ))
      )}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<ApiFetcher />);

function ApiFetcher() {
  const [users, setUsers] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  React.useEffect(() => {
    fetch('https://jsonplaceholder.typicode.com/users')
      .then(res => res.json())
      .then(data => {
        setUsers(data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);
  return (
    <div>
      <h1>User Directory</h1>
      {loading ? (
        <p>Loading...</p>
      ) : error ? (
        <p style={{ color: 'red' }}>Failed to load users. Please try again.</p>
      ) : (
        users.map(u => (
          <div key={u.id}>
            <h3>{u.name}</h3>
            <p>{u.email}</p>
          </div>
        ))
      )}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<ApiFetcher />);
